function wordBreak(s: string, wordDict: string[]): boolean {
  const words = new Set(wordDict)
  const ok = new Array<boolean>(s.length + 1).fill(false)
  ok[0] = true
  for (let i = 1; i <= s.length; i++) {
    for (let j = 0; j < i; j++) {
      if (ok[j] && words.has(s.slice(j, i))) {
        ok[i] = true
        break
      }
    }
  }
  return ok[s.length]
}
